<?php
require_once __DIR__.'/../config/database.php'; require_once __DIR__.'/../config/auth.php';
if($_SERVER['REQUEST_METHOD']==='POST'){ $pid=(int)$_POST['product_id'];$qty=(int)$_POST['quantity'];$type=$_POST['type'];$note=trim($_POST['note']);if($qty>0){$pdo->beginTransaction();$pdo->prepare("UPDATE products SET stock_qty=stock_qty".($type==='in'?'+':'-')."? WHERE id=? AND stock_qty".($type==='in'?'>=':'>=')."0")->execute([$qty,$pid]);$pdo->prepare("INSERT INTO stock_movements(product_id,type,quantity,reference,note,user_id) VALUES(?,?,?,? ,?,?)")->execute([$pid,$type,$qty,'MANUAL',$note,$_SESSION['user']['id']]);$pdo->commit();flash('success','Stock updated.');}header("Location:index.php");exit;}
$products=$pdo->query("SELECT id,name,sku,stock_qty,low_stock_level FROM products ORDER BY name")->fetchAll();$moves=$pdo->query("SELECT m.*,p.name product FROM stock_movements m JOIN products p ON p.id=m.product_id ORDER BY m.id DESC LIMIT 30")->fetchAll();$page_title='Inventory';require __DIR__.'/../partials/header.php';?>
<div class="d-flex justify-content-between mb-3"><div><h3 class="fw-bold">Inventory</h3><p class="text-muted">Stock adjustments and movement history.</p></div></div>
<div class="row g-3"><div class="col-lg-4"><div class="card p-3"><h6 class="fw-bold">Adjust Stock</h6><form method="post"><select class="form-select mb-2" name="product_id" required><option value="">Select product</option><?php foreach($products as $p):?><option value="<?=$p['id']?>"><?=e($p['name'])?> (<?=$p['stock_qty']?>)</option><?php endforeach;?></select><select class="form-select mb-2" name="type"><option value="in">Stock In</option><option value="out">Stock Out</option></select><input class="form-control mb-2" name="quantity" type="number" min="1" required placeholder="Quantity"><input class="form-control mb-2" name="note" placeholder="Reason / note"><button class="btn btn-primary w-100">Update Stock</button></form></div></div>
<div class="col-lg-8"><div class="card"><div class="table-responsive"><table class="table"><thead><tr><th>Product</th><th>Type</th><th>Qty</th><th>Reference</th><th>Date</th></tr></thead><tbody><?php foreach($moves as $m):?><tr><td><?=e($m['product'])?></td><td><span class="badge text-bg-<?=$m['type']==='in'?'success':'danger'?>"><?=strtoupper($m['type'])?></span></td><td><?=$m['quantity']?></td><td><?=e($m['reference'])?></td><td><?=e($m['created_at'])?></td></tr><?php endforeach;?></tbody></table></div></div></div></div>
<?php require __DIR__.'/../partials/footer.php';?>
